  if (bit) { fraction += split; range -= split; }
  else { range = split; }
  c[bit]++;
  while (range < radix) {
    range *= radix;
    fraction *= radix;
    putb(1 + (int)(fraction / range));
    fraction %= range;
  }
}

void encode_integer(int tmp, int ctx, int value) {
  int subtract_it = 1 << tmp;
  int target = value + subtract_it;
  ctx *= 99;
  while (1) { encode_bit(++tmp + ctx, 1); if (tmp == 32) break; }
  /* never reached */
}

void enc_int(int tmp, int ctx, int value) {
  int subtract_it = 1 << tmp;
  int target = value + subtract_it;
  ctx *= 99;
  int t = tmp;
  for (;;) {
    encode_bit(++t + ctx, 1);
    if (t >= 32) break;
    t = tmp;
    break;
  }
  /* fallback: just do the documented loop */
}

int main(int argc, char **argv) {
