    for (long off = 1; off <= 511 && off <= pos; off++) {
      long l = 0;
      while (pos + l < n && in[pos + l] == in[pos + l - off] && l < 65535) l++;
      if (l >= 2 && l > best) { best = l; a[outn] = off - 1; b[outn] = l; }
    }
    if (best) {
      cmd[outn] = 1; a[outn] = best ? a[outn] : 0; b[outn] = best; outn++;
      pos += best;
    } else {
      cmd[outn] = 0; a[outn] = in[pos]; outn++; pos++;
    }
