void eb(int ctx, int bit) {
  int *c = cc + ctx * 2;
  int split = range * -~c[0] / (c[0] + c[1] + 2);
  if (bit) { fraction += split; range -= split; }
  else range = split;
  c[bit]++;
  while (range < radix) {
    range *= radix;
    fraction *= radix;
    putb(1 + (fraction / range));
    fraction %= range;
  }
}

void ei(int tmp, int ctx, int value) {
  int subtract_it = 1 << tmp;
  int target = value + subtract_it;
  int c = ctx * 99;
  int t = tmp;
  int k = 0;
  while (k < 31) { eb(++t + c, 1); k++; }
  eb(++t + c, 0);
  t = tmp; k = 0;
  while (k < tmp) { eb(t + c, target & 1); target >>= 1; k++; }
}

int main(int argc, char **argv) {
  static char in[20000];
  long n = 0, r;
  FILE *inf = fopen(argv[1], "rb");
