  long cmd[12000], a[12000], b[12000];
  while (pos < n) {
    long best = 0, boff = 0;
    for (long off = 1; off <= 511 && off <= pos; off++) {
      long l = 0;
      while (pos + l < n && in[pos + l] == in[pos + l - off] && l < 65535) l++;
      if (l >= 2 && l > best) { best = l; boff = off; }
